#include <stdio.h>

int main(void) {
    long long D, A, N;
    if (scanf("%lld %lld %lld", &D, &A, &N) != 3) return 0;

    long long days = 32 - N;
    long long inc_days = (N - 1 > 14) ? 14 : (N - 1);
    long long daily = D + inc_days * A;
    long long total = days * daily;

    printf("%lld\n", total);
    return 0;
}
```

